INSERT INTO chat_conversation (user_id, title, message_count, last_message, create_time, update_time, deleted) VALUES
(2, 'JVM 内存模型探讨', 3, 'JVM 内存模型包含堆、栈、方法区、程序计数器和本地方法栈，堆内存还分为新生代与老年代。', '2026-07-24 09:12:30', '2026-07-24 09:18:45', 0),
(2, 'Spring Boot 学习答疑', 4, 'Spring Boot 通过 spring.factories 注册自动配置类，自定义 Starter 只需提供 AutoConfiguration 与条件注解。', '2026-07-25 10:05:20', '2026-07-25 10:22:10', 0),
(3, 'React Hook 入门', 3, 'useEffect 用于处理副作用，第二个参数控制依赖变化时才重新执行回调。', '2026-07-24 14:30:00', '2026-07-24 14:42:18', 0),
(3, '机器学习基础概念', 4, '监督学习需要标签数据，无监督学习不需要；过拟合可通过正则化、增加数据量等方式缓解。', '2026-07-25 15:08:50', '2026-07-25 15:25:33', 0);
INSERT INTO chat_message (conversation_id, user_id, role, content, doc_references, token_count, create_time, update_time, deleted) VALUES
(1, 2, 'user', '什么是 JVM 内存模型？', '', 60, '2026-07-24 09:12:30', '2026-07-24 09:12:30', 0),
(1, 2, 'assistant', 'JVM 内存模型包含堆、栈、方法区、程序计数器和本地方法栈。堆是对象分配的主要区域，栈用于存储方法调用栈帧。', '5', 150, '2026-07-24 09:15:10', '2026-07-24 09:15:10', 0),
(1, 2, 'user', '堆内存如何分代？', '', 50, '2026-07-24 09:18:45', '2026-07-24 09:18:45', 0),
(2, 2, 'user', 'Spring Boot 的自动配置原理是什么？', '', 70, '2026-07-25 10:05:20', '2026-07-25 10:05:20', 0),
(2, 2, 'assistant', 'Spring Boot 通过 @EnableAutoConfiguration 加载 META-INF/spring.factories 中注册的自动配置类，结合 @Conditional 系列注解按需生效。', '5', 180, '2026-07-25 10:10:33', '2026-07-25 10:10:33', 0),
(2, 2, 'user', '如何自定义 Starter？', '', 50, '2026-07-25 10:18:00', '2026-07-25 10:18:00', 0),
(2, 2, 'assistant', '创建一个 AutoConfiguration 类并配合 @ConditionalOnClass 等条件注解，再在 spring.factories 中注册即可被 Spring Boot 自动加载。', '5', 200, '2026-07-25 10:22:10', '2026-07-25 10:22:10', 0),
(3, 3, 'user', 'React 的 useState 怎么用？', '', 50, '2026-07-24 14:30:00', '2026-07-24 14:30:00', 0),
(3, 3, 'assistant', '使用 const [state, setState] = useState(initialValue) 在函数组件中声明状态，调用 setState 触发组件重新渲染。', '2', 160, '2026-07-24 14:36:22', '2026-07-24 14:36:22', 0),
(3, 3, 'user', 'useEffect 有什么作用？', '', 50, '2026-07-24 14:42:18', '2026-07-24 14:42:18', 0),
(4, 3, 'user', '什么是监督学习？', '', 50, '2026-07-25 15:08:50', '2026-07-25 15:08:50', 0),
(4, 3, 'assistant', '监督学习是从带标签的训练数据中学习输入到输出的映射关系，常见任务包括分类和回归，例如垃圾邮件识别、房价预测。', '9', 190, '2026-07-25 15:14:30', '2026-07-25 15:14:30', 0),
(4, 3, 'user', '什么是过拟合？', '', 50, '2026-07-25 15:20:05', '2026-07-25 15:20:05', 0),
(4, 3, 'assistant', '过拟合指模型在训练集上表现很好但在测试集上泛化能力差，可通过正则化、增加数据量、Dropout、早停等方式缓解。', '9', 200, '2026-07-25 15:25:33', '2026-07-25 15:25:33', 0);
