INSERT INTO learning_mistake (user_id, question, wrong_answer, correct_answer, category, difficulty, review_count, last_review_time, mastered, source, create_time, update_time, deleted) VALUES
(2, '快速排序最坏时间复杂度是多少？', 'O(n log n)', 'O(n^2)，当选择的基准值每次都是最大或最小元素时退化。', '算法', 3, 5, '2026-07-22 10:00:00', 0, '测验生成', '2026-07-15 09:30:00', '2026-07-22 10:00:00', 0),
(2, 'React useEffect 的清理函数在何时执行？', '只在组件卸载时执行', '在组件卸载时和每次 effect 重新执行前都会调用清理函数。', '前端', 2, 3, '2026-07-20 14:20:00', 0, '智能测验', '2026-07-16 11:00:00', '2026-07-20 14:20:00', 0),
(2, 'TCP 三次握手的过程是怎样的？', 'SYN, ACK, SYN-ACK', 'SYN → SYN-ACK → ACK。客户端先发送 SYN，服务端回复 SYN-ACK，客户端再发送 ACK 确认连接。', 'AI', 3, 7, '2026-07-18 16:45:00', 0, '代码练习', '2026-07-10 08:00:00', '2026-07-18 16:45:00', 0),
(2, 'JavaScript 闭包的本质是什么？', '闭包是一个函数返回另一个函数', '闭包是函数与其词法环境的组合，内部函数可以访问外部函数作用域中的变量，即使外部函数已返回。', '前端', 2, 2, '2026-07-11 09:30:00', 0, '测验生成', '2026-07-08 10:15:00', '2026-07-11 09:30:00', 0),
(2, 'Python GIL 的作用和局限是什么？', 'GIL 保证所有线程安全执行', 'GIL 是全局解释器锁，保证同一时刻只有一个线程执行 Python 字节码，限制了多线程 CPU 并行能力。', 'AI', 2, 1, '2026-07-21 13:00:00', 0, '智能写作', '2026-07-19 15:30:00', '2026-07-21 13:00:00', 0),
(2, 'HashMap 的默认初始容量是多少？', '16', '16，且必须是 2 的幂次方，这样可以用位运算代替取模运算提高效率。', '后端', 1, 4, '2026-07-23 11:20:00', 1, '代码练习', '2026-07-12 14:00:00', '2026-07-23 11:20:00', 0),
(2, 'Vue3 的响应式原理基于什么？', 'Object.defineProperty', 'Proxy。Vue3 使用 ES6 的 Proxy 替代 Object.defineProperty 实现响应式，可以检测到对象属性的添加和删除。', '前端', 2, 6, '2026-07-24 16:00:00', 1, '智能测验', '2026-07-14 09:00:00', '2026-07-24 16:00:00', 0),
(2, 'MySQL 中 InnoDB 引擎的默认隔离级别是？', 'READ COMMITTED', 'REPEATABLE READ（可重复读），这是 InnoDB 的默认事务隔离级别。', '后端', 2, 2, '2026-07-17 10:45:00', 0, '测验生成', '2026-07-13 13:30:00', '2026-07-17 10:45:00', 0),
(2, 'HTTP 状态码 304 表示什么？', '重定向', '304 Not Modified，表示资源未修改，客户端可以使用缓存的版本。', '前端', 1, 3, '2026-07-19 15:15:00', 1, '代码练习', '2026-07-11 11:00:00', '2026-07-19 15:15:00', 0),
(2, 'Spring Bean 的作用域 singleton 表示？', '每个请求一个实例', '单例模式，整个 Spring 容器中只有一个 Bean 实例，是默认作用域。', '后端', 1, 1, '2026-07-25 09:00:00', 0, '智能测验', '2026-07-20 14:30:00', '2026-07-25 09:00:00', 0);
INSERT INTO community_post (user_id, title, content, category, tags, like_count, comment_count, view_count, is_essence, status, create_time, update_time, deleted) VALUES
(2, 'Java HashMap 为什么线程不安全？深入源码分析', '最近在面试中经常被问到 HashMap 线程安全问题，今天花时间从 JDK 源码角度梳理一下 HashMap 在多线程场景下可能出现的问题，包括扩容时的环形链表、并发 put 导致的数据丢失等。', '技术问答', 'Java,并发编程,源码分析', 128, 32, 1200, 1, 1, '2026-07-25 08:00:00', '2026-07-25 10:30:00', 0),
(3, '从零搭建 Vue3 + TypeScript 项目经验总结', '分享一下最近使用 Vue3 组合式 API 和 TypeScript 从零搭建一个中型项目的经验，包括目录结构设计、状态管理方案选型、接口层封装以及踩过的坑。', '学习心得', 'Vue3,TypeScript,项目实战', 86, 18, 920, 0, 1, '2026-07-25 05:00:00', '2026-07-25 09:15:00', 0),
(4, '机器学习入门路线推荐（含免费资源）', '整理了一份适合零基础的机器学习入门路线，从数学基础到经典算法再到实战项目，每一步都附带了免费的学习资源和推荐教材。', '资源分享', '机器学习,学习路线', 204, 45, 2300, 1, 1, '2026-07-24 14:00:00', '2026-07-25 08:00:00', 0),
(5, '字节跳动前端三面面经：从基础到系统设计', '上周通过了字节跳动前端岗的三面面试，分享完整的面试经历和题目，包括 JavaScript 基础、React 原理、性能优化以及最后的系统设计题。', '面试经验', '面试经验,前端,系统设计', 167, 56, 3100, 1, 1, '2026-07-23 16:30:00', '2026-07-25 11:00:00', 0),
(2, '推荐几个提升编程效率的 VS Code 插件', '分享我日常开发中离不开的几个 VS Code 插件，涵盖代码质量检查、自动补全增强、Git 辅助和调试工具，极大提升了编码效率和代码质量。', '资源分享', 'VS Code,工具推荐', 93, 24, 780, 0, 1, '2026-07-22 10:00:00', '2026-07-24 15:30:00', 0),
(3, 'React 19 新特性解析：Server Components 实战', 'React 19 带来了许多令人兴奋的新特性，其中 Server Components 是最受关注的功能之一。本文将从实际项目角度分享如何优雅地使用 Server Components。', '技术问答', 'React,前端,Server Components', 156, 38, 1800, 0, 1, '2026-07-21 09:00:00', '2026-07-24 20:00:00', 0),
(4, '大模型微调实战经验分享（LoRA 方法）', '最近做了几个大模型微调的项目，总结一下使用 LoRA 方法进行高效微调的最佳实践，包括数据准备、超参数调优、效果评估等环节。', '学习心得', '大模型,AI,微调,LoRA', 245, 67, 2800, 1, 1, '2026-07-20 13:00:00', '2026-07-25 07:30:00', 0),
(5, 'Docker 容器化部署完全指南', '从基础概念到生产实践，系统介绍 Docker 容器化部署的完整流程，包括镜像构建、容器编排、网络配置、数据持久化和监控告警。', '资源分享', 'Docker,DevOps,部署', 112, 29, 1500, 0, 1, '2026-07-19 11:00:00', '2026-07-23 16:45:00', 0);
